-- [R158b] Chest Chase update. Paste the WHOLE script into the Command Bar in Edit mode (Play stopped).
-- It checks every script is the exact version it was built for, saves a backup in ServerStorage, then installs.
-- Undo any time: require(game.ServerStorage.ChestChase_R158b_Backup.Installer)("undo")   Redo: ...("install")
-- Objects this update retires are moved (not deleted) into ServerStorage.ChestChase_R158b_Backup.Retired; undo moves them back.
assert(not game:GetService('RunService'):IsRunning(),'[R158b] Stop Play first.')
local storage=game:GetService('ServerStorage')
-- ASCII-only transport keeps embedded sources independent of pasted Unicode and indentation.
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local values={};for i=1,#alphabet do values[alphabet:sub(i,i)]=i-1 end
local function decode(text)
    local out={}
    for i=1,#text,4 do
        local a,b,c,d=text:sub(i,i),text:sub(i+1,i+1),text:sub(i+2,i+2),text:sub(i+3,i+3)
        local n=assert(values[a])*262144+assert(values[b])*4096+(values[c] or 0)*64+(values[d] or 0)
        out[#out+1]=string.char(math.floor(n/65536)%256)
        if c~='=' then out[#out+1]=string.char(math.floor(n/256)%256) end
        if d~='=' then out[#out+1]=string.char(n%256) end
    end
    return table.concat(out)
end
local function sha256(text)
    local band,bxor,bnot,rshift,ror=bit32.band,bit32.bxor,bit32.bnot,bit32.rshift,bit32.rrotate
    local k={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2}
    local h={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}
    local bits=#text*8
    text=text..string.char(128)..string.rep(string.char(0),(55-#text)%64)
    local length={};for i=7,0,-1 do length[#length+1]=string.char(math.floor(bits/2^(8*i))%256) end
    text=text..table.concat(length)
    for offset=1,#text,64 do
        local w={}
        for i=0,15 do local a,b,c,d=text:byte(offset+i*4,offset+i*4+3);w[i]=a*16777216+b*65536+c*256+d end
        for i=16,63 do
            local a,b=w[i-15],w[i-2]
            w[i]=(w[i-16]+bxor(ror(a,7),ror(a,18),rshift(a,3))+w[i-7]+bxor(ror(b,17),ror(b,19),rshift(b,10)))%4294967296
        end
        local a,b,c,d,e,f,g,j=table.unpack(h)
        for i=0,63 do
            local t1=(j+bxor(ror(e,6),ror(e,11),ror(e,25))+bxor(band(e,f),band(bnot(e),g))+k[i+1]+w[i])%4294967296
            local t2=(bxor(ror(a,2),ror(a,13),ror(a,22))+bxor(band(a,b),band(a,c),band(b,c)))%4294967296
            j=g;g=f;f=e;e=(d+t1)%4294967296;d=c;c=b;b=a;a=(t1+t2)%4294967296
        end
        for i,v in ipairs({a,b,c,d,e,f,g,j})do h[i]=(h[i]+v)%4294967296 end
    end
    local out={};for _,v in ipairs(h)do out[#out+1]=string.format('%08x',v)end;return table.concat(out)
end
-- Retire paths are arrays of names (a name may contain '/'), never '/'-joined strings.
local function display(names)
    local out={}
    for i,name in ipairs(names)do out[#out+1]=name:match('^[%a_][%w_]*$')and(i>1 and'.'..name or name)or('["'..name..'"]')end
    return table.concat(out)
end
-- Walks the names down from game. nil when something on the way is missing; refuses when a name matches several siblings.
local function findPath(names)
    local item=game
    for _,name in ipairs(names)do
        local found,count=nil,0
        for _,child in ipairs(item:GetChildren())do if child.Name==name then found=child;count+=1 end end
        assert(count<2,'[R158b] Ambiguous: '..count..' objects are named "'..name..'" in '..item:GetFullName()..' (looking for '..display(names)..'). Nothing changed.')
        if count==0 then return nil end
        item=found
    end
    return item
end
-- A StringValue.Value must be shorter than 200,000 bytes, so text of CHUNK bytes or more is stored as a Folder of numbered StringValues
-- ('1'..'n', each shorter than CHUNK, cut only at UTF-8 character boundaries). Shorter text stays one StringValue.
local CHUNK=100000
local function storeText(parent,name,text)
    if #text<CHUNK then local v=Instance.new('StringValue');v.Name=name;v.Value=text;v.Parent=parent;return end
    local folder=Instance.new('Folder');folder.Name=name;local n,i=0,1
    while i<=#text do
        local j=math.min(i+CHUNK-2,#text)
        while j>i and j<#text and text:byte(j+1)>=128 and text:byte(j+1)<192 do j-=1 end
        n+=1;local v=Instance.new('StringValue');v.Name=tostring(n);v.Value=text:sub(i,j);v.Parent=folder;i=j+1
    end
    folder:SetAttribute('Bytes',#text);folder:SetAttribute('Chunks',n);folder.Parent=parent
end
-- The text storeText saved under `name` in entry; refuses a missing, duplicated, incomplete or resized backup.
local function loadText(entry,name)
    local found,count=nil,0
    for _,child in ipairs(entry:GetChildren())do if child.Name==name then found=child;count+=1 end end
    local bad='[R158b] Damaged source backup: '..name..' in '..entry:GetFullName()
    assert(count==1,bad)
    if found:IsA('StringValue')then return found.Value end
    local kids=found:GetChildren();local n=found:GetAttribute('Chunks')
    assert(found:IsA('Folder')and n==#kids,bad)
    local parts={}
    for i=1,n do
        local part,c=nil,0
        for _,k in ipairs(kids)do if k.Name==tostring(i)then part=k;c+=1 end end
        assert(c==1 and part:IsA('StringValue'),bad);parts[i]=part.Value
    end
    local text=table.concat(parts);assert(#text==found:GetAttribute('Bytes'),bad);return text
end

local existing=storage:FindFirstChild('ChestChase_R158b_Backup')
if existing then
 -- Same build pasted again: redo. A different build with the same backup name must never run the old one.
 -- Same build = Build attribute, or an Installer identical to this one (pastes before the attribute never set it).
 local installer=existing:FindFirstChild('Installer')
 local same=existing:GetAttribute('Build')=='7209b266ec9056387804dac0462e904b3cdc0e82759b61151d4b204984c32835'or(installer~=nil and installer:IsA('ModuleScript')and sha256(installer.Source)=='7209b266ec9056387804dac0462e904b3cdc0e82759b61151d4b204984c32835')
 assert(same,'[R158b] An older [R158b] backup is in ServerStorage. Undo it first: require(game.ServerStorage.ChestChase_R158b_Backup.Installer)("undo") then delete ServerStorage.ChestChase_R158b_Backup and paste this again. Nothing changed.')
 existing:SetAttribute('Build','7209b266ec9056387804dac0462e904b3cdc0e82759b61151d4b204984c32835')
 require(existing:WaitForChild('Installer'))('install');return
end
local specs={{Path="ReplicatedStorage/BatConfig",Class="ModuleScript",BeforeBytes=4479,AfterBytes=4467,BeforeSHA256="ebc6dde9b78f5273673c08d282f09b5f61cd9050ca9d979a07714664bbe55d81",AfterSHA256="76a2a95695069828668c43413b169b6c7d2acfbfe6e2043cfd5bd858b1ac1fdc"},{Path="ReplicatedStorage/ClientFxBudget",Class="ModuleScript",BeforeBytes=3214,AfterBytes=3549,BeforeSHA256="45bd6feb33779de99eb22f55dcbc7bdd41bda992d3c73aa2ead2e96eb55a5f49",AfterSHA256="3617b9ecd69f3db85805ec3cd6c3b5319041bd3a9542557c4447f136291ffe31"},{Path="ServerScriptService/ChestChaseServer/Config",Class="ModuleScript",BeforeBytes=190235,AfterBytes=190236,BeforeSHA256="ab00d4c58bff86238bcdcf2035b973f4dad82c562b4e24026f96f17453efc4cc",AfterSHA256="90c2bfd950c6e2b7e4c5f13c2fabf5e481315fde226dcc672188e05fd894af40"},{Path="StarterPlayer/StarterPlayerScripts/BatClient",Class="LocalScript",BeforeBytes=17861,AfterBytes=17703,BeforeSHA256="5470e1071fd2ed91b2841ae5906a753fc8e180a9566672d880d4a2f85f9f3194",AfterSHA256="df8fc45d8b7b7504f7c6c53553a964e02da3318ea494b9518dda47c1e38de2f7"},{Path="StarterPlayer/StarterPlayerScripts/TrackHoleClient",Class="LocalScript",BeforeBytes=9746,AfterBytes=10382,BeforeSHA256="5df2d8156d06b175203edbf11033ef2b5158aa578a9b9bcfbb0df198c1249271",AfterSHA256="1e141ad143df142c8582adf6f1d5066b794761a57d095bde33ac7b1cf8f413f1"},{Path="ReplicatedStorage/DroppedPackLook158b",Class="ModuleScript",New=true,AfterBytes=5420,AfterSHA256="58d78309d11b2411e68e7a978ad57fa5f57a76b7f1d50b29eb597a5fdcde6672"},{Path="StarterPlayer/StarterPlayerScripts/DroppedPackHighlight158b",Class="LocalScript",New=true,AfterBytes=10877,AfterSHA256="6feba8ec6d938041c10c68d5c15a8edb915b4e16a48dc1d965d1e8dedf042798"}}
local retireList={}
local patches={{Path="ReplicatedStorage/BatConfig",Patches={{652,323,table.concat({""})}}},{Path="ReplicatedStorage/ClientFxBudget",Patches={{2197,24,table.concat({""})},{2547,0,table.concat({"dXNlZAplbmQKZnVuY3Rpb24gQi5IaWdobGlnaHRSb29tKCkKIHJldHVybiA="})},{2574,4,table.concat({"Qi5IaWdobGlnaHRzVXNlZCgp"})}}},{Path="ServerScriptService/ChestChaseServer/Config",Patches={{189173,0,table.concat({"Yg=="})}}},{Path="StarterPlayer/StarterPlayerScripts/BatClient",Patches={{1909,14,table.concat({"fSkgLS0gKFIxNThiLCBvd25lcjogInRoZXJlIGlzIG9ubHkgYSBzb3VuZCBlZmZlY3QgZm9yIGhpdHRpbmcgc29tZW9uZSI6IGEgc3dpbmcgbWFrZXMgbm8gc291bmQgb2YgaXRzIG93biwgb25seSB0aGUgc2xhcCBvZiBhIGhpdDsgbm8gd2hvb3NoIGlzIHByZWxvYWRlZA=="})},{6038,12,table.concat({""})},{6176,0,table.concat({"LS0gUjE1OGIgKG93bmVyKTogYSBzd2luZyBpcyBTSUxFTlQsIHlvdXJzIGFuZCBldmVyeW9uZSBlbHNlJ3M7IHRoZSBvbmx5IHNvdW5kIGlzIHRoZSBzbGFwIG9mIGEgaGl0IChjbGFpbSgpLCBiZWxvdzsgdGhlIHNlcnZlcidzIHBhY2tldCBmb3Igb3RoZXIgcGxheWVycycgaGl0cykuCg=="})},{6243,148,table.concat({""})},{6579,311,table.concat({"VHJhaWxSYW5nZQ=="})}}},{Path="StarterPlayer/StarterPlayerScripts/TrackHoleClient",Patches={{1463,0,table.concat({"bG9jYWwgZGlnRGVmOw=="})},{1518,0,table.concat({"O2lmIHMuS2V5PT0nRGlnJ2FuZCBzLklkfj0nJ3RoZW4gZGlnRGVmPXMgZW5k"})},{1646,0,table.concat({""})},{1716,1,table.concat({""})},{7960,10,table.concat({"VGh1ZA=="})}}},{Path="ReplicatedStorage/DroppedPackLook158b",Patches={{1,0,table.concat({"",""})}}},{Path="StarterPlayer/StarterPlayerScripts/DroppedPackHighlight158b",Patches={{1,0,table.concat({"","","",""})}}}}
local engineSource=decode(table.concat({"","","","","",""}))
assert(sha256(engineSource)=='7209b266ec9056387804dac0462e904b3cdc0e82759b61151d4b204984c32835','[R158b] The pasted text was damaged while copying. Nothing changed.')
local editor=game:GetService('ScriptEditorService')
local function unique(parent,name)
 local found,count=nil,0
 for _,child in ipairs(parent:GetChildren())do if child.Name==name then found=child;count+=1 end end
 assert(count==1,'[R158b] Missing or duplicated object: '..name..' in '..parent:GetFullName()..'. Nothing changed.');return found
end
local function resolve(path)local item=game;for name in path:gmatch('[^/]+')do item=unique(item,name)end;return item end
local byPath={};for _,p in ipairs(patches)do byPath[p.Path]=p.Patches end
local backup=Instance.new('Folder');backup.Name='ChestChase_R158b_Backup'
local sources=Instance.new('Folder');sources.Name='Sources';sources.Parent=backup
for i,spec in ipairs(specs)do
 if spec.New then
  -- A script this update adds. It is created parked inside the backup; the installer moves it into place.
  local parentPath,name=spec.Path:match('^(.*)/([^/]+)$');local home=resolve(parentPath)
  assert(home:FindFirstChild(name)==nil,'[R158b] '..spec.Path..' already exists. Nothing changed.')
  local after=''
  for _,p in ipairs(byPath[spec.Path])do after=after..decode(p[3])end
  assert(#after==spec.AfterBytes and sha256(after)==spec.AfterSHA256,'[R158b] Patch check failed for '..spec.Path..'. Nothing changed.')
  local entry=Instance.new('Folder');entry.Name=string.format('%02d',i);entry:SetAttribute('Path',spec.Path);entry:SetAttribute('New',true);entry.Parent=sources
  storeText(entry,'After',after)
  local item=Instance.new(spec.Class);item.Name=name;item.Source=after;item.Parent=entry
  local t=Instance.new('ObjectValue');t.Name='Target';t.Value=item;t.Parent=entry
  continue
 end
 local item=resolve(spec.Path)
 assert(item.ClassName==spec.Class,'[R158b] '..spec.Path..' is a '..item.ClassName..', expected '..spec.Class..'. Nothing changed.')
 local before=editor:GetEditorSource(item)
 assert(item.Source==before,'[R158b] Close or save unsaved edits in '..spec.Path..' first. Nothing changed.')
 assert(#before==spec.BeforeBytes and sha256(before)==spec.BeforeSHA256,'[R158b] '..spec.Path..' is not the version this update was built for. Nothing changed.')
 local after=before;local list=byPath[spec.Path]
 table.sort(list,function(a,b)return a[1]>b[1]end)
 for _,p in ipairs(list)do after=after:sub(1,p[1]-1)..decode(p[3])..after:sub(p[1]+p[2])end
 assert(#after==spec.AfterBytes and sha256(after)==spec.AfterSHA256,'[R158b] Patch check failed for '..spec.Path..'. Nothing changed.')
 local entry=Instance.new('Folder');entry.Name=string.format('%02d',i);entry:SetAttribute('Path',spec.Path);entry.Parent=sources
 storeText(entry,'Before',before);storeText(entry,'After',after)
 local t=Instance.new('ObjectValue');t.Name='Target';t.Value=item;t.Parent=entry
end
if #retireList>0 then
 -- Objects to retire are looked up now, before anything changes: a missing one is skipped (reported by the installer),
 -- one name matching two siblings refuses the whole update. The installer moves them; here they are only recorded.
 local retired=Instance.new('Folder');retired.Name='Retired';retired.Parent=backup
 for i,names in ipairs(retireList)do
  local item=findPath(names)
  local entry=Instance.new('Folder');entry.Name=string.format('%02d',i);entry:SetAttribute('Index',i);entry:SetAttribute('Path',display(names));entry.Parent=retired
  if item==nil then entry:SetAttribute('Missing',true)
  else
   assert(item~=storage and not storage:IsDescendantOf(item),'[R158b] '..display(names)..' contains the backup and cannot be retired. Nothing changed.')
   local target=Instance.new('ObjectValue');target.Name='Target';target.Value=item;target.Parent=entry
   local parked=Instance.new('Folder');parked.Name='Parked';parked.Parent=entry
   -- Every Script/LocalScript inside is remembered with its Disabled state; the installer disables them while parked.
   local list=Instance.new('Folder');list.Name='Scripts';list.Parent=entry
   local scripts=item:IsA('BaseScript')and{item}or{}
   for _,d in ipairs(item:GetDescendants())do if d:IsA('BaseScript')then scripts[#scripts+1]=d end end
   for n,s in ipairs(scripts)do
    local v=Instance.new('ObjectValue');v.Name='S'..n;v.Value=s;v:SetAttribute('Disabled',s.Disabled==true);v.Parent=list
   end
  end
 end
end
local installer=Instance.new('ModuleScript');installer.Name='Installer';installer.Source=engineSource;installer.Parent=backup
backup:SetAttribute('SourceCount',#specs);backup:SetAttribute('RetireCount',#retireList);backup:SetAttribute('Build','7209b266ec9056387804dac0462e904b3cdc0e82759b61151d4b204984c32835');backup:SetAttribute('State','Built');backup.Parent=storage
require(installer)('install')
print('[R158b] Backup: ServerStorage.ChestChase_R158b_Backup   Undo: require(game.ServerStorage.ChestChase_R158b_Backup.Installer)("undo")')
if #retireList>0 then print('[R158b] Retired objects are parked in ServerStorage.ChestChase_R158b_Backup.Retired; undo puts them back where they were.') end
